// Zeby request.getPart(...)/getParts() w ogole zadzialaly, serwlet
// MUSI miec jawnie skonfigurowana obsluge multipart. W embedded
// Tomcacie robimy to programowo na obiekcie Wrapper:

Wrapper wrapper = Tomcat.addServlet(context, "nazwa", new MojServlet());
wrapper.setMultipartConfigElement(
        new MultipartConfigElement(katalogTymczasowy));

// KLUCZOWE: to trzeba zrobic PRZED tomcat.start() - najprostszy,
// pewny sposob, zeby na pewno bylo gotowe zanim przyjdzie pierwsze
// zadanie. MultipartConfigElement(String location) - "location" to
// katalog, w ktorym serwer moze tymczasowo zapisywac wieksze czesci
// pliku (bufor na dysku).

// java.net.http.HttpClient NIE MA wbudowanego buildera multipart -
// cialo trzeba zbudowac RECZNIE, jako tablice bajtow o dokladnej
// strukturze, jakiej oczekuje serwer:
//
//   --<boundary>\r\n
//   Content-Disposition: form-data; name="file"; filename="test.txt"\r\n
//   Content-Type: text/plain\r\n
//   \r\n
//   <bajty pliku>\r\n
//   --<boundary>--\r\n

out.write(("--" + BOUNDARY + "\r\n").getBytes(UTF_8));
out.write(("Content-Disposition: form-data; name=\"file\"; filename=\"test.txt\"\r\n").getBytes(UTF_8));
out.write(("Content-Type: text/plain\r\n\r\n").getBytes(UTF_8));
out.write(fileBytes);
out.write(("\r\n--" + BOUNDARY + "--\r\n").getBytes(UTF_8));

// Naglowek zadania musi dokladnie odpowiadac uzytej granicy:
// Content-Type: multipart/form-data; boundary=<boundary>

protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
    try {
        Part filePart = req.getPart("file");
        String submittedFileName = filePart.getSubmittedFileName();
        byte[] content = filePart.getInputStream().readAllBytes();

        resp.getWriter().write("Odebrano plik '" + submittedFileName + "' ("
                + content.length + " bajtow)");
    } catch (Exception e) {
        resp.setStatus(HttpServletResponse.SC_BAD_REQUEST);
        resp.getWriter().write("Blad przetwarzania uploadu: " + e.getMessage());
    }
}
